import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-09-23","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-09-23","date":"2020-09-23T00:00:00.000Z","updated":"2020-09-24T00:00:00.000Z","tags":["Ceph","分布式存储","结构测试与修复","垃圾收集","请求处理流程"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-09-23.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-09-23.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-09-23.md"};function o(n,e,h,s,u,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统中的结构测试与修复讨论" tabindex="-1">会议主题：Ceph存储系统中的结构测试与修复讨论 <a class="header-anchor" href="#会议主题-ceph存储系统中的结构测试与修复讨论" aria-label="Permalink to &quot;会议主题：Ceph存储系统中的结构测试与修复讨论&quot;">​</a></h4><h4 id="会议时间-2020-09-23" tabindex="-1">会议时间：2020-09-23 <a class="header-anchor" href="#会议时间-2020-09-23" aria-label="Permalink to &quot;会议时间：2020-09-23&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>结构测试与修复进展</strong></p><ul><li>上周重点讨论了结构测试的修复，特别是请求执行中的间隔变化问题。</li><li>提出在tri-mutex中引入暂停和恢复语义，以解决中断请求的顺序问题。</li></ul></li><li><p><strong>中断请求处理</strong></p><ul><li>讨论了中断请求在tri-mutex中的处理方式，确保中断请求能够重新获取锁。</li><li>强调在PG间隔变化时，所有请求需重新排队。</li></ul></li><li><p><strong>请求处理流程</strong></p><ul><li>详细讨论了IO请求的处理流程，包括排队、获取锁、读取对象上下文等步骤。</li><li>确保在PG间隔变化时，所有请求从处理流程的起点重新开始。</li></ul></li><li><p><strong>内存状态管理</strong></p><ul><li>讨论了在PG间隔变化时，如何处理内存中的对象上下文和状态。</li><li>决定在PG间隔变化时，所有请求丢弃所有内存状态，重新从起点开始处理。</li></ul></li><li><p><strong>垃圾收集（Garbage Collection）</strong></p><ul><li>讨论了Ceph存储系统中的垃圾收集机制，包括如何管理空间和避免大量垃圾收集操作。</li><li>介绍了两个可调参数：目标空闲空间和使用空间与不可用空间的比率。</li></ul></li><li><p><strong>其他工作进展</strong></p><ul><li>讨论了中断可 futures 的调试进展。</li><li>介绍了GH对象的集成和随机插入的单元测试进展。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>所有请求在PG间隔变化时需要重新排队，从处理流程的起点重新开始。</li><li>在PG间隔变化时，丢弃所有内存状态，避免使用过时的对象上下文和状态。</li><li>继续优化垃圾收集机制，确保系统空间的有效管理。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续进行结构测试的修复工作，确保请求处理的正确性和顺序。</li><li>完成中断可 futures 的调试，并提交相关PR。</li><li>完成GH对象的集成和单元测试，修复相关bug。</li><li>继续优化垃圾收集机制，确保系统的稳定性和性能。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的“tri-mutex”、“PG interval change”、“re-queue”等关键词是Ceph存储系统中的专业术语，需要特别注意其在系统中的具体含义和应用。</li></ul><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4><h4 id="下次会议预告-具体日期和时间" tabindex="-1">下次会议预告：[具体日期和时间] <a class="header-anchor" href="#下次会议预告-具体日期和时间" aria-label="Permalink to &quot;下次会议预告：[具体日期和时间]&quot;">​</a></h4>',14)])])}const c=a(r,[["render",o]]);export{_ as __pageData,c as default};
